ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns ns0 http://tempuri.org/
ns ns1 http://www.etb.com.co/orquestador
ns ns2 http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Solicitudes
fun isEmptyObj (obj) = obj match {
    case is Object -> (obj pluck $) reduce ((item, accumulator=true) -> accumulator and isEmptyObj(item))
    else -> isEmpty(obj)
}
fun appendNamespace(data, nameSpace) =
  data match {
    case is Object -> data mapObject do {
      nameSpace#"$($$)": appendNamespace($, nameSpace)
    }
    else -> data
}
---
{
	soapenv#Envelope: {
		soapenv#Header: {},
		soapenv#Body: {
		    ns0#CreacionAgendaRemedy: {
		        ns0#creacionObjeto: {
		            ns1#ParametrosCreacion: payload.CreacionAgendaRemedy.creacionObjeto.ParametrosCreacion mapObject ((value, key, index) -> if (!isEmptyObj(value)) ({
		    ns2#ParametroCreacion: appendNamespace(value, ns2)
		}) else ns2#ParametroCreacion: null )
		        }
		    }
		}
	}
}
